$urls = @('https://mirror.cachyos.org/ISO/desktop/', 'https://cdn.cachyos.org/ISO/desktop/')
foreach ($u in $urls) {
    $html = Get-WebContent -Uri $u
    if ($html) {
        $matches = [regex]::Matches($html, 'href="(\d+)/"')
        if ($matches.Count -gt 0) {
            $latestDir = $matches | ForEach-Object { $_.Groups[1].Value } | Sort-Object { [long]$_ } -Descending | Select-Object -First 1
            $filename  = "cachyos-desktop-linux-$latestDir.iso"
            return @{ Version = $latestDir; Url = "https://mirror.cachyos.org/ISO/desktop/$latestDir/$filename"; Filename = $filename }
        }
    }
}
return $null

