if ($chk -and $chk -match 'clonezilla-live-(\d+\.\d+\.\d+-\d+)-amd64\.iso') {
    $fn = $Matches[0]
    $ver = $Matches[1]
    $url = "https://downloads.sourceforge.net/project/clonezilla/clonezilla_live_stable/$ver/$fn"
    return @{ Version = $ver; Url = $url; Filename = $fn; ChecksumUrl = 'https://clonezilla.org/downloads/stable/data/CHECKSUMS.TXT' }
}
return $null

$html = Get-WebContent -Uri 'https://cdn.openbsd.org/pub/OpenBSD/'
if ($html) {
    $vers = [regex]::Matches($html, 'href="(\d+\.\d+)/"') | ForEach-Object { $_.Groups[1].Value } | Sort-Object { [version](ConvertTo-VersionString $_) } -Descending
    foreach ($v in $vers) {
        $sub = Get-WebContent -Uri "https://cdn.openbsd.org/pub/OpenBSD/$v/amd64/"
        if ($sub -and $sub -match 'install(\d+)\.iso') {
            $fn = $Matches[0]
            return @{ Version = $v; Url = "https://cdn.openbsd.org/pub/OpenBSD/$v/amd64/$fn"; Filename = $fn; ChecksumUrl = "https://cdn.openbsd.org/pub/OpenBSD/$v/amd64/SHA256" }
        }
    }
}
return $null

$html = Get-WebContent -Uri 'https://cdn.netbsd.org/pub/NetBSD/images/'
if ($html) {
    $vers = [regex]::Matches($html, 'href="(\d+\.\d+(\.\d+)?)/"') | ForEach-Object { $_.Groups[1].Value } | Sort-Object { [version](ConvertTo-VersionString $_) } -Descending
    foreach ($v in $vers) {
        $sub = Get-WebContent -Uri "https://cdn.netbsd.org/pub/NetBSD/images/$v/"
        if ($sub -and $sub -match "(NetBSD-$([regex]::Escape($v))-amd64\.iso)") {
            $fn = $Matches[1]
            return @{ Version = $v; Url = "https://cdn.netbsd.org/pub/NetBSD/images/$v/$fn"; Filename = $fn; ChecksumUrl = "https://archive.netbsd.org/pub/NetBSD-archive/images/$v/SHA512" }
        }
    }
}
return $null

$html = Get-WebContent -Uri 'https://mirror.checkdomain.de/dragonflybsd/iso-images/'
if ($html) {
    $matches = [regex]::Matches($html, 'href="(dfly-x86_64-([\d\.]+)_REL\.iso)"')
    if ($matches.Count -gt 0) {
        $latest = $matches | Sort-Object { [version]($_.Groups[2].Value) } -Descending | Select-Object -First 1
        $fn = $latest.Groups[1].Value
        $ver = $latest.Groups[2].Value
        return @{ Version = $ver; Url = "https://mirror.checkdomain.de/dragonflybsd/iso-images/$fn"; Filename = $fn; ChecksumUrl = "https://mirror.checkdomain.de/dragonflybsd/iso-images/md5.txt" }
    }
}
return $null

